(()=>{'use strict';document.querySelectorAll('.header .nav a').forEach(a=>a.addEventListener('click',()=>{if(!a.classList.contains('nav-home'))document.querySelector('.header .nav')?.classList.remove('open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.nav.open')?.classList.remove('open');document.querySelector('.portal-sidebar.open')?.classList.remove('open')}});})();
